
import bisect

def solution(intervals, queries):
    
    sl = sorted(intervals) # O(N . log N)
    n = len(sl)
    starts = [x[0] for x in sl] # O(N)
    
    tree = [float('-inf')] * (2 * n)
    for i in range(n):
        tree[n + i] = intervals[i][1]
    for i in range(n - 1, 0, -1):
        tree[i] = max(tree[2 * i], tree[2 * i + 1])
        
    def update(idx, val):
        idx += n
        tree[idx] = val
        while idx > 1:
            idx //= 2
            tree[idx] = max(tree[2 * i], tree[2 * i + 1])
            
    def query_max(l, r):
        res = float('-inf')
        l += n
        r += n
        
        while l < r:
            if l % 2 == 1:
                res = max(res, tree[l])
                l += 1
                
            if r % 2 == 1:
                r -= 1
                res = max(res, tree[r])
                
            l //= 2
            r //= 2
            
        return res
    
    pos_map = {(sl[i][0],sl[i][1]): i for i in range(n)}
    active_count = n
    results = []
    
    for op, a, b in queries:
        if op == 0:
            idx_limit = bisect.bisect_right(starts, b)
            if idx_limit > 0 and query_max(0, idx_limit) >= a:
                results.append(True)
            else:
                results.append(False)
                
        elif op == 1:
            if (a,b) in pos_map:
                update(pos_map[(a,b)], float('-inf'))
                del pos_map[(a,b)]
                active_count -= 1
                
            results.append(active_count)
                
    return results



