    @timeout_decorator.timeout(2)
    def test_06(self):
        n = 100000
        k = 100000
        
        # Generating intervals with pattern [x0, x4]
        intervals = [[i * 10, i * 10 + 4] for i in range(n)]
        
        queries = []
        expected_result = []

        # Creating queries
        for _ in range(k):
            operation = 0
            a = random.randint(0, n * 10 - 6)
            b = a + random.randint(1, 6)  # Length of interval up to 6

            # Predict result for intersection query based on last digit condition
            last_digit_a = a % 10
            last_digit_b = b % 10
            
            intersects = not (5 <= last_digit_a <= last_digit_b)

            expected_result.append(intersects)
            queries.append([operation, a, b])
        
        # Get the result from the efficient solution
        result = solution(intervals, queries)
        
        self.assertEqual(result, expected_result)